def maxCircularSumAtMostK(nums, k):
    from collections import deque
    n = len(nums)
    m = 2 * n
    P = [0] * (m + 1)
    for i in range(m):
        P[i + 1] = P[i] + nums[i % n]
    best = None
    dq = deque()
    for e in range(1, m + 1):
        s_new = e - 1
        while dq and P[dq[-1]] >= P[s_new]:
            dq.pop()
        dq.append(s_new)
        while dq[0] < e - k:
            dq.popleft()
        val = P[e] - P[dq[0]]
        if best is None or val > best:
            best = val
    return best
